package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

const insert = "INSERT INTO tags (name) VALUES ($1) RETURNING id"

func main() {
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	defer conn.Close(ctx)
	_, err = conn.Exec(ctx, "CREATE TABLE tags (id int GENERATED ALWAYS AS IDENTITY, name text UNIQUE NOT NULL)")
	if err != nil {
		log.Fatal(err)
	}

	// Three statements, one round trip. Each callback runs as its result arrives.
	b := &pgx.Batch{}
	for _, name := range []string{"go", "pgx", "çay"} {
		b.Queue(insert, name).QueryRow(func(row pgx.Row) error {
			var id int
			err := row.Scan(&id)
			fmt.Println("inserted", name, "as", id)
			return err
		})
	}
	err = conn.SendBatch(ctx, b).Close() // Close waits for every result
	fmt.Println("batch 1:", err)

	// A batch runs in one implicit transaction: the failure undoes "sql" too.
	b = &pgx.Batch{}
	b.Queue(insert, "sql")
	b.Queue(insert, "go") // duplicate
	b.Queue("DELETE FROM tags").Exec(func(ct pgconn.CommandTag) error {
		fmt.Println("never runs:", ct)
		return nil
	})
	err = conn.SendBatch(ctx, b).Close()
	fmt.Println("batch 2:", err)

	var names []string
	err = conn.QueryRow(ctx, "SELECT array_agg(name ORDER BY id) FROM tags").Scan(&names)
	fmt.Println("tags:", names, err)
}

files.examples/03_cancel.go:
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgconn/ctxwatch"
)

type setup struct {
	name      string
	configure func(*pgx.ConnConfig)
}

func main() {
	ctx := context.Background()
	setups := []setup{
		{"default", func(*pgx.ConnConfig) {}},
		{"cancel request", func(c *pgx.ConnConfig) {
			c.BuildContextWatcherHandler = func(pc *pgconn.PgConn) ctxwatch.Handler {
				return &pgconn.CancelRequestContextWatcherHandler{Conn: pc, DeadlineDelay: 2 * time.Second}
			}
		}},
		{"statement_timeout", func(c *pgx.ConnConfig) {
			c.RuntimeParams["statement_timeout"] = "100ms" // session default, set at connect
		}},
	}

	for _, s := range setups {
		cfg, err := pgx.ParseConfig(os.Getenv("DATABASE_URL"))
		if err != nil {
			log.Fatal(err)
		}
		s.configure(cfg)
		conn, err := pgx.ConnectConfig(ctx, cfg)
		if err != nil {
			log.Fatal(err)
		}

		short, cancel := context.WithTimeout(ctx, 500*time.Millisecond)
		_, err = conn.Exec(short, "SELECT pg_sleep(3)")
		cancel()
		fmt.Printf("%s: %v\n", s.name, err)
		fmt.Printf("  errors.Is(err, context.DeadlineExceeded)=%t, connection closed=%t\n",
			errors.Is(err, context.DeadlineExceeded), conn.IsClosed())
		conn.Close(ctx)
	}
}
